"""Options screen and tab bar art (your painted "wizard's study" sheet), cut out of the checkerboard.
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

TRACK_IN = (51, 10, 552, 48)          # slider_track: the dark well the fill goes in (left, top, right, bottom)
TOGGLE_IN = (7, 7, 104, 48)           # toggle_track: inside of the pill
SCROLL_TOP = 25                       # scroll: rows above this are only the banners
SCROLL_SLICE = (150, 300)             # scroll: columns kept as-is left of / right of these; the middle is tiled
CANDLES = ((281, 33), (762, 35), (88, 333))   # flames painted in background.png (wall sconces, desk candle)
PNG = {
  'background': ('jpg', ''),
  'candle_sconce': ('png', ''),
  'divider': ('png', ''),
  'footer_ornament': ('png', ''),
  'icon_camera': ('png', ''),
  'icon_difficulty': ('png', ''),
  'icon_display': ('png', ''),
  'icon_music': ('png', ''),
  'icon_sound': ('png', ''),
  'icon_vibration': ('png', ''),
  'icon_weather': ('png', ''),
  'knob_off': ('png', ''),
  'knob_on': ('png', ''),
  'scroll': ('png', ''),
  'slider_handle': ('png', ''),
  'slider_track': ('png', ''),
  'tab_babies': ('png', ''),
  'tab_bestiary': ('png', ''),
  'tab_den': ('png', ''),
  'tab_eggs': ('png', ''),
  'tab_hoard': ('png', ''),
  'tab_home': ('png', ''),
  'tab_options': ('png', ''),
  'tab_quests': ('png', ''),
  'tab_roster': ('png', ''),
  'tab_selected': ('png', ''),
  'tabbar': ('png', ''),
  'title_plaque': ('png', ''),
  'toggle_track': ('png', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
